import 'package:flutter/material.dart';import 'package:google_mobile_ads/google_mobile_ads.dart';import 'package:nfc_writer/data/services/app_ads_service.dart';class AppInit{  AppInit._();  static AppInit? _instance;  static AppInit get instance =>      _instance ??= AppInit._();  Future<void> init()async{    WidgetsFlutterBinding.ensureInitialized();    AppAdsService.instance.initialize();  }}